              {cms.infoCards.map((c,i)=><div key={c.id} className="p-2 rounded-lg border border-slate-200 bg-slate-50/50 space-y-2"><div className="flex justify-between"><Badge className={c.visible?'bg-emerald-50 text-emerald-700':'bg-slate-200'}>{c.visible?'ظاهر':'مخفي'}</Badge><div className="flex gap-1"><Button variant="ghost" size="sm" className="h-6" onClick={()=>updA('infoCards',i,{visible:!c.visible})}>{c.visible?<EyeOff size={10}/>:<Eye size={10}/>}</Button><Button variant="ghost" size="sm" className="h-6 text-red-500" onClick={()=>rmA('infoCards',c.id)}><X size={10}/></Button></div></div><div className="grid grid-cols-2 md:grid-cols-4 gap-2"><Input value={c.title} onChange={e=>updA('infoCards',i,{title:e.target.value})} placeholder="العنوان" className="h-7 text-[10px]" /><Input value={c.value} onChange={e=>updA('infoCards',i,{value:e.target.value})} placeholder="القيمة" className="h-7 text-[10px]" /><IconBtn value={c.icon} onChange={v=>updA('infoCards',i,{icon:v}as any)} /><input type="color" value={c.color} onChange={e=>updA('infoCards',i,{color:e.target.value}as any)} className="h-7 w-8 rounded cursor-pointer" /></div><Input value={c.change} onChange={e=>updA('infoCards',i,{change:e.target.value})} placeholder="↗ +12%" className="h-7 text-[10px]" /></div>)}
