              <Button variant="outline" size="sm" className="h-7 text-[10px]" onClick={()=>up('charts',{charts:[...cms.charts,mkChart()]})}><Plus size={10}/> إضافة</Button>
              {cms.charts.map((ch,i)=><div key={ch.id} className="p-2 rounded-lg border border-slate-200 bg-slate-50/50 space-y-2"><div className="flex justify-between"><Badge className={ch.visible?'bg-emerald-50 text-emerald-700':'bg-slate-200'}>{ch.visible?'ظاهر':'مخفي'}</Badge><Button variant="ghost" size="sm" className="h-6 text-red-500" onClick={()=>rmA('charts',ch.id)}><X size={10}/></Button></div><div className="grid grid-cols-2 gap-2"><Input value={ch.title} onChange={e=>updA('charts',i,{title:e.target.value})} placeholder="العنوان" className="h-7 text-[10px]" /><Select value={ch.type} onValueChange={v=>updA('charts',i,{type:v as any})}><SelectTrigger className="h-7 text-[10px]"><SelectValue/></SelectTrigger><SelectContent>{['line','bar','pie','area'].map(x=><SelectItem key={x} value={x}>{x}</SelectItem>)}</SelectContent></Select></div></div>)}
